{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    if not isinstance(nodes, list) or len(nodes) < 2:
        raise ValueError("Invalid nodes: must be a list with at least 2 elements")
    if not isinstance(core_distance, dict):
        raise ValueError("Invalid core_distance: must be a dict")
    if not isinstance(distances, list):
        raise ValueError("Invalid distances: must be a list")

    for node in nodes:
        if node not in core_distance:
            raise ValueError(f"Missing core distance for node {node}")

    edges = []
    for entry in distances:
        if len(entry) != 3:
            raise ValueError("Each distance entry must have exactly 3 elements")
        u, v, d = entry[0], entry[1], entry[2]
        if u not in core_distance:
            raise ValueError(f"Node {u} in distances not found in core_distance")
        if v not in core_distance:
            raise ValueError(f"Node {v} in distances not found in core_distance")
        mr = max(core_distance[u], core_distance[v], d)
        # Canonicalize undirected endpoints lexicographically
        if u > v:
            u, v = v, u
        edges.append((mr, u, v))

    # Sort by mutual reachability weight, then by first endpoint, then second endpoint
    edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find with path compression and union by rank
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n = len(nodes)

    for mr, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == n - 1:
                break

    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected; cannot build a spanning tree")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }
"}
